            file=sys.stderr,
        )

    def _send_json(self, status: int, value: Any, headers: dict[str, str] | None = None) -> None:
        encoded = json.dumps(
            value, ensure_ascii=False, separators=(",", ":"), allow_nan=False
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        if headers:
            for name, header_value in headers.items():
                self.send_header(name, header_value)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(encoded)

    def _error(self, status: int, message: str, headers: dict[str, str] | None = None) -> None:
        self._send_json(status, {"error": message}, headers)

    def _route(self) -> tuple[str, str | None]:
        parsed = urlsplit(self.path)
        if parsed.query or parsed.fragment:
            return "unknown", None
        if parsed.path == "/health":
            return "health", None
        if parsed.path == "/v1/keys":
            return "keys", None
        if parsed.path.startswith(API_PREFIX):
            encoded_key = parsed.path[len(API_PREFIX) :]
            try:
                if any(
                    encoded_key[index] == "%"
                    and (
                        index + 2 >= len(encoded_key)
                        or any(char not in "0123456789abcdefABCDEF" for char in encoded_key[index + 1 : index + 3])
                    )
                    for index in range(len(encoded_key))
                ):
                    raise ValueError
                key = unquote_to_bytes(encoded_key).decode("utf-8", errors="strict")
            except (UnicodeDecodeError, ValueError):
                return "invalid_key", None
            if not key or "/" in key:
                return "invalid_key", None
            return "kv", key
        return "unknown", None

    def _read_json_object(self) -> dict[str, Any] | None:
        transfer_encoding = self.headers.get("Transfer-Encoding")
        if transfer_encoding is not None:
            self._error(400, "chunked request bodies are not supported")
            self.close_connection = True
            return None
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            self._error(411, "Content-Length is required")
            return None
        try:
            length = int(raw_length, 10)
            if length < 0:
                raise ValueError
        except ValueError:
            self._error(400, "invalid Content-Length")
            self.close_connection = True
            return None
        if length > MAX_BODY:
            self._error(413, "request body exceeds 1 MiB limit")
            self.close_connection = True
            return None
        try:
            raw = self.rfile.read(length)
            if len(raw) != length:
                raise ValueError("incomplete request body")
            document = json.loads(
                raw.decode("utf-8"), parse_constant=Store._reject_constant
            )
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
            self._error(400, "malformed JSON")
            return None
        if not isinstance(document, dict):
            self._error(400, "request body must be a JSON object")
            return None
        return document

    def do_GET(self) -> None:
        route, key = self._route()
        try:
            if route == "health":
                self._send_json(200, {"status": "ok"})
            elif route == "keys":
                self._send_json(200, {"keys": self.server.store.keys()})
            elif route == "kv":
                assert key is not None
                found, value = self.server.store.get(key)
                if found:
                    self._send_json(200, {"key": key, "value": value})
                else:
                    self._error(404, "key not found")
            elif route == "invalid_key":
                self._error(400, "invalid key")
            else:
                self._error(404, "route not found")
        except StoreError as exc:
            print(exc, file=sys.stderr)
            self._error(500, "storage error")

    def do_PUT(self) -> None:
        route, key = self._route()
        if route == "invalid_key":
            self._error(400, "invalid key")
            return
        if route != "kv":
            self._error(404, "route not found")
            return
        document = self._read_json_object()
        if document is None:
            return
        if "value" not in document or not set(document).issubset({"value", "ttl_seconds"}):
            self._error(400, "body must contain value and optional ttl_seconds")
            return
        ttl: float | None = None
        if "ttl_seconds" in document:
            raw_ttl = document["ttl_seconds"]
            if isinstance(raw_ttl, bool) or not isinstance(raw_ttl, (int, float)):
                self._error(400, "ttl_seconds must be a finite number greater than zero")
                return
            try:
                ttl = float(raw_ttl)
            except (OverflowError, ValueError):
                ttl = math.nan
            if not math.isfinite(ttl) or ttl <= 0 or not math.isfinite(time.time() + ttl):
                self._error(400, "ttl_seconds must be a finite number greater than zero")
                return
        try:
            # It was parsed as JSON, but this also documents/polices persistence safety.
            json.dumps(document["value"], allow_nan=False)
            assert key is not None
            created = self.server.store.put(key, document["value"], ttl)
            self._send_json(201 if created else 200, {"key": key, "value": document["value"]})
        except (ValueError, TypeError):
            self._error(400, "value is not valid JSON")
        except StoreError as exc:
            print(exc, file=sys.stderr)
            self._error(500, "storage error")

    def do_DELETE(self) -> None:
        route, key = self._route()
        if route == "invalid_key":
            self._error(400, "invalid key")
            return
        if route != "kv":
            self._error(404, "route not found")
            return
        try:
            assert key is not None
            if self.server.store.delete(key):
                self.send_response(204)
                self.send_header("Content-Length", "0")
                self.end_headers()
            else:
                self._error(404, "key not found")
        except StoreError as exc:
            print(exc, file=sys.stderr)
            self._error(500, "storage error")

    def _unsupported(self) -> None:
        self._error(405, "method not allowed", {"Allow": "GET, PUT, DELETE"})

    do_POST = _unsupported
    do_PATCH = _unsupported
    do_HEAD = _unsupported
    do_OPTIONS = _unsupported


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True, type=Path)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = Server((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup failed: {exc}", file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(_signum: int, _frame: Any) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
import http.client
import json
import os
import signal
import subprocess
import sys
import tempfile
import threading
import time
import unittest
from pathlib import Path
from urllib.parse import quote


class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.data = Path(self.temp.name) / "nested" / "data.json"
        self.start()

    def tearDown(self):
        self.stop()
        self.temp.cleanup()

    def start(self):
        self.process = subprocess.Popen(
            [sys.executable, "server.py", "--host", "127.0.0.1", "--port", "0", "--data", str(self.data)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        line = self.process.stdout.readline()
        self.assertRegex(line, r"^LISTENING \d+\n$")
        self.port = int(line.split()[1])

    def stop(self):
        if getattr(self, "process", None) and self.process.poll() is None:
            self.process.send_signal(signal.SIGTERM)
            self.process.wait(timeout=3)
        if getattr(self, "process", None):
            self.assertEqual(self.process.returncode, 0, self.process.stderr.read())

    def request(self, method, path, body=None, headers=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        if isinstance(body, (dict, list)):
            body = json.dumps(body)
        connection.request(method, path, body=body, headers=headers or {})
        response = connection.getresponse()
        raw = response.read()
        content_type = response.getheader("Content-Type")
        connection.close()
        return response.status, content_type, json.loads(raw) if raw else None

    def test_crud_encoding_sorting_and_restart(self):
        self.assertEqual(self.request("GET", "/health"), (200, "application/json", {"status": "ok"}))
        for key, value in [("z", [1, True]), ("hello world", {"x": None}), ("é", "yes")]:
            status, _, payload = self.request("PUT", "/v1/kv/" + quote(key), {"value": value})
            self.assertEqual(status, 201)
            self.assertEqual(payload, {"key": key, "value": value})
        self.assertEqual(self.request("PUT", "/v1/kv/z", {"value": 2})[0], 200)
        self.assertEqual(self.request("GET", "/v1/keys")[2], {"keys": ["hello world", "z", "é"]})
        self.assertEqual(self.request("DELETE", "/v1/kv/hello%20world"), (204, None, None))
        self.stop()
        self.start()
        self.assertEqual(self.request("GET", "/v1/kv/z")[2], {"key": "z", "value": 2})
        self.assertEqual(self.request("GET", "/v1/kv/hello%20world")[0], 404)

    def test_ttl_and_validation(self):
        self.assertEqual(self.request("PUT", "/v1/kv/short", {"value": 1, "ttl_seconds": .08})[0], 201)
        time.sleep(.12)
        self.assertEqual(self.request("GET", "/v1/kv/short")[0], 404)
        for ttl in [0, -1, True, "2"]:
            self.assertEqual(self.request("PUT", "/v1/kv/a", {"value": 1, "ttl_seconds": ttl})[0], 400)
        for path in ["/v1/kv/", "/v1/kv/a%2Fb", "/v1/kv/%FF", "/v1/kv/%GG"]:
            self.assertEqual(self.request("GET", path)[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/a", "no", {"Content-Length": "2"})[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/a", {})[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/a", {"value": 1, "extra": 2})[0], 400)
        self.assertEqual(self.request("POST", "/health", {})[0], 405)
        self.assertEqual(self.request("GET", "/missing")[0], 404)

    def test_body_limit_and_concurrency(self):
        oversized = json.dumps({"value": "x" * 1024 * 1024})
        self.assertEqual(self.request("PUT", "/v1/kv/large", oversized)[0], 413)
        errors = []
        def write(index):
            try:
                status = self.request("PUT", f"/v1/kv/k{index}", {"value": index})[0]
                if status != 201:
                    errors.append(status)
            except Exception as exc:
                errors.append(exc)
        threads = [threading.Thread(target=write, args=(i,)) for i in range(20)]
        for thread in threads: thread.start()
        for thread in threads: thread.join()
        self.assertEqual(errors, [])
        self.assertEqual(len(self.request("GET", "/v1/keys")[2]["keys"]), 20)
        with self.data.open(encoding="utf-8") as stream:
            self.assertEqual(len(json.load(stream)["entries"]), 20)


if __name__ == "__main__":
    unittest.main()
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON service with atomic file persistence, TTLs,
thread-safe concurrent requests, and graceful SIGTERM shutdown.

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Use port `0` to select a free port. The first stdout line reports it as
`LISTENING <port>`; request diagnostics go to stderr.

## API

- `PUT /v1/kv/<url-encoded-key>` — body `{"value": <any JSON>, "ttl_seconds": <positive number>}`;
  `ttl_seconds` is optional.
- `GET /v1/kv/<url-encoded-key>` — fetch a live value.
- `DELETE /v1/kv/<url-encoded-key>` — delete a live value.
- `GET /v1/keys` — list live keys in lexicographic order.
- `GET /health` — liveness response.

Requests and non-empty responses use JSON. Request bodies are limited to 1 MiB.

## Tests

```sh
python3 -m unittest -v
```
